using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (Path.GetFullPath(Path.GetDirectoryName(Application.dataPath)) != @"C:\ConRoi_CheckoutTest")
                throw new Exception("Wrong project");
            if (EditorApplication.isPlaying || EditorSceneManager.GetActiveScene().isDirty)
                throw new Exception("No discard or runtime scene save allowed");
            EditorSceneManager.OpenScene("Assets/ConRoi/Modules/TichHop/Scenes/ConRoi_Chinh.unity");
            r.Log("Opened unchanged integration entry explicitly after first import; did not save legacy recovery or discard dirty scene.");
        }
    }
}

